package com.bank.threepatterns.account;

import java.util.logging.Logger;

// Account Service OWNS the accounts database. Others must call it,
// never query its tables directly (Database-per-Service).
public class AccountServiceClient {
    private static final Logger log = Logger.getLogger(AccountServiceClient.class.getName());
    private boolean down = false;

    public void simulateOutage(boolean down) { this.down = down; }

    public String holderName(String accountId) {
        if (down) throw new RuntimeException("Account Service unavailable");
        log.info(() -> "REMOTE lookup holder for " + accountId);
        return accountId.equals("SAV2001") ? "Rajesh Kumar" : "Priya Sharma";
    }
}
