package com.bank.threepatterns.resilience;

import java.util.function.Supplier;
import java.util.logging.Logger;

// Minimal circuit breaker: CLOSED → OPEN after too many failures,
// then HALF_OPEN to test recovery.
public class CircuitBreaker {
    private static final Logger log = Logger.getLogger(CircuitBreaker.class.getName());
    enum State { CLOSED, OPEN, HALF_OPEN }
    private State state = State.CLOSED;
    private int failures = 0;
    private final int threshold;

    public CircuitBreaker(int threshold) { this.threshold = threshold; }

    public <T> T call(Supplier<T> action, Supplier<T> fallback) {
        if (state == State.OPEN) {
            log.warning("Breaker OPEN — fail fast, serving fallback");
            state = State.HALF_OPEN;              // next real call is a trial
            return fallback.get();
        }
        try {
            T result = action.get();
            if (state == State.HALF_OPEN) { state = State.CLOSED; failures = 0; }
            return result;
        } catch (RuntimeException ex) {
            failures++;
            log.severe("Call failed (" + failures + "/" + threshold + "): " + ex.getMessage());
            if (failures >= threshold) state = State.OPEN;
            return fallback.get();
        }
    }
    public String state() { return state.name(); }
}
