package com.bank.threepatterns.payment;

import com.bank.threepatterns.account.AccountServiceClient;
import com.bank.threepatterns.resilience.CircuitBreaker;
import java.util.logging.Logger;

// Payment Service owns its OWN data; it reaches account data only via a call,
// protected by a circuit breaker.
public class PaymentService {
    private static final Logger log = Logger.getLogger(PaymentService.class.getName());
    private final AccountServiceClient accountClient;
    private final CircuitBreaker breaker;

    public PaymentService(AccountServiceClient accountClient, CircuitBreaker breaker) {
        this.accountClient = accountClient;
        this.breaker = breaker;
    }

    public String resolveHolder(String accountId) {
        return breaker.call(
            () -> accountClient.holderName(accountId),
            () -> "NAME_UNAVAILABLE (fallback)"
        );
    }
}
