package com.bank.threepatterns.gateway;

import com.bank.threepatterns.payment.PaymentService;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// API Gateway: authenticate once, then aggregate from services.
public class ApiGateway {
    private static final Logger log = Logger.getLogger(ApiGateway.class.getName());
    private final PaymentService paymentService;

    public ApiGateway(PaymentService paymentService) { this.paymentService = paymentService; }

    public Map<String, String> dashboard(String jwt, String accountId) {
        if (jwt == null || jwt.isBlank()) throw new SecurityException("Missing JWT");
        log.info(() -> "Gateway authenticated request for " + accountId);
        Map<String, String> response = new LinkedHashMap<>();
        response.put("accountId", accountId);
        response.put("holder", paymentService.resolveHolder(accountId)); // aggregation
        return response;
    }
}
