package com.bank.threepatterns;

import com.bank.threepatterns.account.AccountServiceClient;
import com.bank.threepatterns.gateway.ApiGateway;
import com.bank.threepatterns.payment.PaymentService;
import com.bank.threepatterns.resilience.CircuitBreaker;
import java.util.logging.Logger;

public class ThreePatternsDemo {
    private static final Logger log = Logger.getLogger(ThreePatternsDemo.class.getName());

    public static void main(String[] args) {
        AccountServiceClient accountClient = new AccountServiceClient();
        CircuitBreaker breaker = new CircuitBreaker(2);
        PaymentService paymentService = new PaymentService(accountClient, breaker);
        ApiGateway gateway = new ApiGateway(paymentService);

        log.info("=== Healthy: gateway auth + aggregate ===");
        log.info("Response: " + gateway.dashboard("valid-jwt", "SAV2001"));

        log.info("=== Account Service down: breaker trips ===");
        accountClient.simulateOutage(true);
        for (int i = 1; i <= 3; i++) {
            log.info("Attempt " + i + " → " + gateway.dashboard("valid-jwt", "SAV2001")
                   + " [breaker=" + breaker.state() + "]");
        }
    }
}
